examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    Box {
        MonarchEventChip(
            title = {{event.title}},
            variant = MonarchEventChipVariant.Bar,
            color = Color(0xFF0F766E),
            time = {{chipTime}},
            onClick = { open = true },
        )
        MonarchPopover(expanded = open, onDismissRequest = { open = false }, label = {{event.title}}) {
            MonarchEventPopover(
                title = {{event.title}},
                subtitle = {{event.detail}},
                start = {{event.start|millis}},
                end = {{event.end|millis}},
                status = MonarchEventChipStatus.{{event.status|pascal}},
                color = Color(0xFF0F766E),
                details = listOf(
                    MonarchEventPopoverDetail({{details.0.label}}, {{details.0.value}}),
                    MonarchEventPopoverDetail({{details.1.label}}, {{details.1.value}}),
                ),
                timeZone = {{timeZone}},
            ) {
                MonarchButton(text = {{actions.0}}, onClick = { open = false }, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
                MonarchButton(text = {{actions.1}}, onClick = { open = false }, variant = MonarchButtonVariant.DangerSubtle, size = MonarchButtonSize.Sm)
            }
        }
    }
}

examples.setupTemplate:
var open by remember { mutableStateOf(true) }
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

